import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const s="/assets/datentypen.Vj7cowMB.svg",g=JSON.parse('{"title":"Log-Meldungen","description":"","frontmatter":{"order":3,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/03.referenz/03.log-meldungen.md"},"headers":[],"relativePath":"de/adapter/wled/referenz/log-meldungen.md","filePath":"de/adapter/wled/referenz/log-meldungen.md","lastUpdated":null}'),d={name:"de/adapter/wled/referenz/log-meldungen.md"};function r(o,e,l,h,c,u){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="log-meldungen" tabindex="-1">Log-Meldungen <a class="header-anchor" href="#log-meldungen" aria-label="Permalink to &quot;Log-Meldungen&quot;">​</a></h1><p><a id="warning-state-attribute-definition-missing"></a></p><h2 id="was-bedeutet-die-warnung-state-attribute-definition-missing" tabindex="-1">Was bedeutet die Warnung &quot;State attribute definition missing&quot;? <a class="header-anchor" href="#was-bedeutet-die-warnung-state-attribute-definition-missing" aria-label="Permalink to &quot;Was bedeutet die Warnung &quot;State attribute definition missing&quot;?&quot;">​</a></h2><p><strong>Kurz:</strong> Die Meldung ist harmlos, du musst nichts tun. WLED liefert ein Feld, für das der Adapter keine eigene Beschreibung hat. Der Adapter legt den Datenpunkt trotzdem an. Seit v0.7.1 steht die Meldung nur noch auf der Log-Stufe „debug“.</p><p>So sieht die Meldung aus:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>State attribute definition missing for : &lt;Feld&gt; with value : &lt;Wert&gt;</span></span></code></pre></div><h3 id="was-dahintersteckt" tabindex="-1">Was dahintersteckt <a class="header-anchor" href="#was-dahintersteckt" aria-label="Permalink to &quot;Was dahintersteckt&quot;">​</a></h3><p>Der Adapter hat eine Liste mit allen WLED-Feldern, die er kennt. Darin steht für jedes Feld der Name, der Datentyp, die Rolle und ob du den Datenpunkt schreiben darfst. Bringt eine neue WLED-Firmware ein Feld mit, das in der Liste fehlt, legt der Adapter den Datenpunkt so an:</p><ul><li>Der Name ist der Feldname aus WLED.</li><li>Der Datentyp richtet sich nach dem Wert, den WLED liefert.</li><li>Der Datenpunkt ist nur lesbar. Schreiben über diesen Datenpunkt geht nicht.</li></ul><p>Beispiele aus der Vergangenheit sind <code>cct</code>, <code>n</code> und <code>liveseg</code>. Sie kamen mit neuen WLED-Versionen und stehen inzwischen in der Liste.</p><p>Willst du ein solches Feld trotzdem setzen, schickst du es als JSON-Befehl über den Datenpunkt <code>action</code>. Fehlt dir ein Feld dauerhaft, melde es in einem <a href="https://github.com/DrozmotiX/ioBroker.wled/issues" target="_blank" rel="noreferrer">GitHub-Issue</a>.</p><h3 id="altere-versionen" tabindex="-1">Ältere Versionen <a class="header-anchor" href="#altere-versionen" aria-label="Permalink to &quot;Ältere Versionen&quot;">​</a></h3><p><strong>Bis v0.7.0:</strong> Die Meldung erschien als Warnung oder Fehler im normalen Log, teils mit dem Zusatz <code>Sentry disabled, error caught</code>. In v0.5.x konnte sich die Instanz danach beenden. Aktualisiere in diesem Fall den Adapter.</p><p><strong>Bis v0.9.2:</strong> Auf der Stufe „debug“ steht die Meldung bei jeder Aktualisierung des Geräts erneut im Log, immer wieder für dasselbe Feld.</p><p><strong>Ab v0.9.3:</strong> Der Adapter meldet jedes fehlende Feld nur einmal je Start (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/917" target="_blank" rel="noreferrer">#917</a>).</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Wie sende ich einen kompletten JSON-Befehl an WLED aus ioBroker?</a> · <a href="./../fehlerbehebung/verbindung-und-start#adapter-stop-working-after-wled">Warum funktioniert der Adapter nach einem WLED-Firmware-Update nicht mehr?</a></p><p><a id="warnings-about-wrong-data-type"></a></p><h2 id="was-bedeuten-warnungen-zu-falschem-datentyp-oder-fehlendem-val-beim-schreiben-von-states" tabindex="-1">Was bedeuten Warnungen zu falschem Datentyp oder fehlendem &quot;val&quot; beim Schreiben von States? <a class="header-anchor" href="#was-bedeuten-warnungen-zu-falschem-datentyp-oder-fehlendem-val-beim-schreiben-von-states" aria-label="Permalink to &quot;Was bedeuten Warnungen zu falschem Datentyp oder fehlendem &quot;val&quot; beim Schreiben von States?&quot;">​</a></h2><p><strong>Kurz:</strong> ioBroker prüft jeden Wert, der in einen Datenpunkt geschrieben wird, gegen dessen Datentyp. Passt der Typ nicht, steht eine Warnung im Log. Kommt sie von deinem Skript, schreibst du den Wert im falschen Typ, zum Beispiel <code>&quot;true&quot;</code> als Text statt <code>true</code>. Kommt sie vom Adapter selbst, hilft ein Update.</p><p>So sehen die Meldungen aus:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>State value to set for &quot;wled.0.&lt;MAC&gt;.&lt;State&gt;&quot; has to be type &quot;boolean&quot; but received type &quot;string&quot;</span></span>
<span class="line"><span>State value to set for &quot;wled.0.&lt;MAC&gt;.&lt;State&gt;&quot; has to be one of type &quot;string&quot;, &quot;number&quot;, &quot;boolean&quot; but received type &quot;object&quot;</span></span>
<span class="line"><span>State value to set is invalid for wled.0.&lt;MAC&gt;.&lt;State&gt;: The state is missing the required property val!</span></span></code></pre></div><p>Am Anfang der Log-Zeile steht, wer geschrieben hat. Steht dort <code>wled.&lt;Instanz&gt;</code>, kommt der Wert vom Adapter. Steht dort zum Beispiel <code>javascript.0</code>, kommt er aus deinem Skript.</p><h3 id="welchen-datentyp-erwarten-die-datenpunkte" tabindex="-1">Welchen Datentyp erwarten die Datenpunkte? <a class="header-anchor" href="#welchen-datentyp-erwarten-die-datenpunkte" aria-label="Permalink to &quot;Welchen Datentyp erwarten die Datenpunkte?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Typ</th><th>Beispiel</th></tr></thead><tbody><tr><td><code>on</code></td><td>Wahrheitswert (boolean)</td><td><code>true</code> oder <code>false</code></td></tr><tr><td><code>bri</code></td><td>Zahl</td><td><code>0</code> bis <code>255</code></td></tr><tr><td><code>ps</code></td><td>Zahl</td><td><code>3</code> für Preset 3</td></tr><tr><td><code>pl</code></td><td>Zahl</td><td><code>1</code> für Playlist 1</td></tr><tr><td><code>transition</code></td><td>Zahl</td><td><code>7</code></td></tr><tr><td><code>seg.&lt;Segment&gt;.col.0</code>, <code>.1</code>, <code>.2</code></td><td>Text mit Zahlen in eckigen Klammern</td><td><code>&quot;[255,0,0]&quot;</code> oder mit Weißkanal <code>&quot;[255,0,0,0]&quot;</code></td></tr><tr><td><code>seg.&lt;Segment&gt;.col.0_HEX</code>, <code>.1_HEX</code>, <code>.2_HEX</code></td><td>Text</td><td><code>&quot;#ff0000&quot;</code></td></tr><tr><td><code>action</code></td><td>Text mit JSON</td><td><code>{&quot;on&quot;:true,&quot;bri&quot;:128}</code> als Text</td></tr><tr><td><code>_info._online</code></td><td>Wahrheitswert (boolean), nur lesbar</td><td><code>true</code> oder <code>false</code></td></tr></tbody></table><p>Die Typen von <code>on</code>, <code>bri</code>, <code>ps</code>, <code>pl</code> und <code>transition</code> legt der Adapter beim Anlegen nach dem Wert fest, den WLED liefert. Die Farb-Datenpunkte sind vom Typ „mixed“ und enthalten die Farbe als Text. Beim Schreiben nimmt der Adapter auch <code>&quot;255,0,0&quot;</code> ohne Klammern an.</p><h3 id="so-schreibst-du-die-werte-im-richtigen-typ" tabindex="-1">So schreibst du die Werte im richtigen Typ <a class="header-anchor" href="#so-schreibst-du-die-werte-im-richtigen-typ" aria-label="Permalink to &quot;So schreibst du die Werte im richtigen Typ&quot;">​</a></h3><p>Im Skript übergibst du Zahlen und Wahrheitswerte ohne Anführungszeichen, Farben als Text:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.on&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// nicht &#39;true&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.bri&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// nicht &#39;128&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.ps&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// nicht &#39;3&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.seg.0.col.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[255,0,0]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Text, keine Liste</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.seg.0.col.0_HEX&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#ff0000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>In Blockly bestimmt der Block, den du an „steuere“ oder „aktualisiere“ anhängst, den Typ:</p><ol><li>Für <code>on</code> nimmst du den Logik-Block „wahr“ oder „falsch“. Ein Text-Block mit <code>true</code> liefert Text.</li><li>Für <code>bri</code>, <code>ps</code> und <code>pl</code> nimmst du den Zahl-Block aus „Mathematik“. Ein Text-Block mit <code>3</code> liefert Text.</li><li>Für Farben nimmst du einen Text-Block mit <code>[255,0,0]</code> oder <code>#ff0000</code>. Ein Listen-Block liefert eine Liste, also den Typ „object“.</li></ol><p><img src="`+s+'" alt="Übersicht: Der Logik-Block „wahr“ oder „falsch“ liefert boolean für on. Der Zahl-Block liefert eine Zahl für bri, ps, pl und transition. Ein Text-Block liefert Text für die Farb-Datenpunkte. Ein Text-Block mit true an on und ein Listen-Block an einer Farbe führen zu einer Warnung."></p><h3 id="meldungen-vom-adapter-selbst" tabindex="-1">Meldungen vom Adapter selbst <a class="header-anchor" href="#meldungen-vom-adapter-selbst" aria-label="Permalink to &quot;Meldungen vom Adapter selbst&quot;">​</a></h3><p><strong>Bis v0.9.2:</strong> Ist ein Gerät nicht erreichbar, schreibt der Adapter <code>_info._online</code> als Text. Im Log steht dann <code>State value to set for &quot;wled.0.&lt;MAC&gt;._info._online&quot; has to be type &quot;boolean&quot; but received type &quot;string&quot;</code>. Du musst nichts ändern, die Meldung kommt vom Adapter.</p><p><strong>Ab v0.9.3:</strong> <code>_info._online</code> ist immer ein Wahrheitswert, die Meldung entfällt (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/788" target="_blank" rel="noreferrer">#788</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/794" target="_blank" rel="noreferrer">#794</a>).</p><p>Die Meldung <code>The state is missing the required property val!</code> und Typ-Meldungen zu Datenpunkten unter <code>_info</code> wie <code>_info.mac</code> kamen von Adapterversionen aus 2020 und 2021. Heute überspringt der Adapter leere Werte. Siehst du diese Meldungen noch, aktualisiere den Adapter.</p><h3 id="datenpunkte-die-sich-mit-v0-9-3-andern" tabindex="-1">Datenpunkte, die sich mit v0.9.3 ändern <a class="header-anchor" href="#datenpunkte-die-sich-mit-v0-9-3-andern" aria-label="Permalink to &quot;Datenpunkte, die sich mit v0.9.3 ändern&quot;">​</a></h3><p><strong>Ab v0.9.3:</strong> <code>seg.&lt;Segment&gt;.mi</code> (Segment spiegeln) ist ein Wahrheitswert und lässt sich schreiben (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/918" target="_blank" rel="noreferrer">#918</a>).</p><p><strong>Ab v0.9.3:</strong> <code>time</code> ist eine Zahl (Unix-Zeitstempel) und lässt sich schreiben, um die Uhrzeit des Geräts zu setzen (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/919" target="_blank" rel="noreferrer">#919</a>). Bis v0.9.2 ist <code>time</code> vom Typ „mixed“ und nur lesbar.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/farbe#write-colour-wled-script-blockly">Wie schreibe ich eine Farbe per Skript oder Blockly auf WLED?</a> · <a href="./../fehlerbehebung/befehle-wirken-nicht#script-not-ps-wled-ignores">Warum setzt mein Skript ps oder on nicht?</a> · <a href="./datenpunkte#individual-wled-states-mean">Was bedeuten die einzelnen WLED-Datenpunkte?</a></p><p><a id="errors-about-unreachable-devices-websocket"></a></p><h2 id="was-bedeuten-die-fehler-gerat-nicht-erreichbar-und-websocket-was-closed-before-the-connection-was-established" tabindex="-1">Was bedeuten die Fehler &quot;Gerät nicht erreichbar&quot; und &quot;WebSocket was closed before the connection was established&quot;? <a class="header-anchor" href="#was-bedeuten-die-fehler-gerat-nicht-erreichbar-und-websocket-was-closed-before-the-connection-was-established" aria-label="Permalink to &quot;Was bedeuten die Fehler &quot;Gerät nicht erreichbar&quot; und &quot;WebSocket was closed before the connection was established&quot;?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="sentry-messages-log"></a></p><h2 id="was-sind-die-sentry-meldungen-im-log" tabindex="-1">Was sind die Sentry-Meldungen im Log? <a class="header-anchor" href="#was-sind-die-sentry-meldungen-im-log" aria-label="Permalink to &quot;Was sind die Sentry-Meldungen im Log?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',45)])])}const k=t(d,[["render",r]]);export{g as __pageData,k as default};
